with with_windows as (select id, discount_pct, lag(discount_pct, 2, 0) over (partition by date_trunc('MONTH', starts_on), channel order by starts_on, id) as prev_discount_pct, avg(discount_pct) over (partition by date_trunc('month', ends_on), promo_code order by ends_on, id rows between 6 preceding and 1 preceding) as discount_pct_avg_6_prior, max(discount_pct) over (partition by promo_code, channel) as promo_code_max_discount_pct from promotions where ends_on < '2023-12-01') select case when prev_discount_pct >= 0.28 then 'LARGE' else 'SMALL' end as prev_discount_pct_tier, case when discount_pct >= 0.34 then 'HIGH' else 'LOW' end as discount_pct_tier, approx_percentile(discount_pct_avg_6_prior, 0.9) as discount_pct_avg_6_prior_p90, count(distinct id) as distinct_ids, stddev_samp(discount_pct) as discount_pct_stddev from with_windows group by case when prev_discount_pct >= 0.28 then 'LARGE' else 'SMALL' end, case when discount_pct >= 0.34 then 'HIGH' else 'LOW' end having count(distinct id) > 1 order by discount_pct_tier desc
